// CommandServiceHandler is an implementation of the laelia.v1.CommandService service.
type CommandServiceHandler interface {
	ListCommands(context.Context, *connect.Request[v1.ListCommandsRequest]) (*connect.Response[v1.ListCommandsResponse], error)
	GetCommand(context.Context, *connect.Request[v1.GetCommandRequest]) (*connect.Response[v1.Command], error)
	CancelCommand(context.Context, *connect.Request[v1.CancelCommandRequest]) (*connect.Response[v1.Command], error)
	WatchCommand(context.Context, *connect.Request[v1.WatchCommandRequest], *connect.ServerStream[v1.CommandOutput]) error
	WatchCommandEvents(context.Context, *connect.Request[v1.WatchCommandEventsRequest], *connect.ServerStream[v1.CommandEvent]) error
	RespondPermission(context.Context, *connect.Request[v1.RespondPermissionRequest]) (*connect.Response[emptypb.Empty], error)
	SearchChatHistory(context.Context, *connect.Request[v1.SearchChatHistoryRequest]) (*connect.Response[v1.SearchChatHistoryResponse], error)
	GetCommandContext(context.Context, *connect.Request[v1.GetCommandContextRequest]) (*connect.Response[v1.GetCommandContextResponse], error)
	GetOrCreateConversation(context.Context, *connect.Request[v1.GetOrCreateConversationRequest]) (*connect.Response[v1.GetOrCreateConversationResponse], error)
	ListConversationMessages(context.Context, *connect.Request[v1.ListConversationMessagesRequest]) (*connect.Response[v1.ListConversationMessagesResponse], error)
	ListThreadMessages(context.Context, *connect.Request[v1.ListThreadMessagesRequest]) (*connect.Response[v1.ListThreadMessagesResponse], error)
	ListChannelThreads(context.Context, *connect.Request[v1.ListChannelThreadsRequest]) (*connect.Response[v1.ListChannelThreadsResponse], error)
	CreateChannel(context.Context, *connect.Request[v1.CreateChannelRequest]) (*connect.Response[v1.Conversation], error)
	ListChannels(context.Context, *connect.Request[v1.ListChannelsRequest]) (*connect.Response[v1.ListChannelsResponse], error)
	// ListChannelsForAgent returns every conversation the given agent is a member
	// of (both direct DMs with users and multi-user channels), used by the agent
	// detail page's "Chat" tab. Admin-scoped: gated by laelia.agents.get.
	ListChannelsForAgent(context.Context, *connect.Request[v1.ListChannelsForAgentRequest]) (*connect.Response[v1.ListChannelsForAgentResponse], error)
	GetChannel(context.Context, *connect.Request[v1.GetChannelRequest]) (*connect.Response[v1.Conversation], error)
	UpdateChannel(context.Context, *connect.Request[v1.UpdateChannelRequest]) (*connect.Response[v1.Conversation], error)
	DeleteChannel(context.Context, *connect.Request[v1.DeleteChannelRequest]) (*connect.Response[emptypb.Empty], error)
	AddChannelMember(context.Context, *connect.Request[v1.AddChannelMemberRequest]) (*connect.Response[v1.ChannelMember], error)
	RemoveChannelMember(context.Context, *connect.Request[v1.RemoveChannelMemberRequest]) (*connect.Response[emptypb.Empty], error)
	ListChannelMembers(context.Context, *connect.Request[v1.ListChannelMembersRequest]) (*connect.Response[v1.ListChannelMembersResponse], error)
	SendMessage(context.Context, *connect.Request[v1.SendMessageRequest]) (*connect.Response[v1.ChatMessage], error)
	PostMessage(context.Context, *connect.Request[v1.PostMessageRequest]) (*connect.Response[v1.PostMessageResponse], error)
	// ConvertMessageToTask turns an existing top-level message into a task by
	// attaching task metadata (number, status=TODO, no assignee). Any channel
	// member (user or agent) may convert. Emits a system notification row.
	ConvertMessageToTask(context.Context, *connect.Request[v1.ConvertMessageToTaskRequest]) (*connect.Response[v1.ConvertMessageToTaskResponse], error)
	// ListTasks returns the task board for a conversation: every task (root
	// message with task metadata) in the channel, optionally filtered by status.
	ListTasks(context.Context, *connect.Request[v1.ListTasksRequest]) (*connect.Response[v1.ListTasksResponse], error)
	// CreateTask posts a new top-level task message in a channel (used by agents
	// to break work into subtasks for others to claim). The new task is created
	// unassigned (status TODO); the posting agent does NOT auto-claim it. Emits a
	// system notification row and wakes other agent members.
	CreateTask(context.Context, *connect.Request[v1.CreateTaskRequest]) (*connect.Response[v1.CreateTaskResponse], error)
	// ClaimTask atomically transitions a TODO task to IN_PROGRESS and assigns it
	// to the calling agent, subscribing the agent to the task's thread so approval
	// replies wake it. Returns FAILED_PRECONDITION if the task is already
	// claimed or not in TODO. Emits a system notification row.
	ClaimTask(context.Context, *connect.Request[v1.ClaimTaskRequest]) (*connect.Response[v1.ClaimTaskResponse], error)
	// UnclaimTask releases the calling agent's claim on a task it owns, setting
	// it back to TODO so another agent may claim it. Not allowed on DONE
	// (terminal). Emits a system notification row.
	UnclaimTask(context.Context, *connect.Request[v1.UnclaimTaskRequest]) (*connect.Response[v1.UnclaimTaskResponse], error)
	// UpdateTaskStatus advances a task's status. IN_PROGRESS -> IN_REVIEW marks
	// the assignee's work ready for human review; IN_REVIEW -> DONE marks it
	// complete (the assignee should call this only after detecting the human's
	// approval in the task's thread). Only the assignee may call this. Emits a
	// system notification row.
	UpdateTaskStatus(context.Context, *connect.Request[v1.UpdateTaskStatusRequest]) (*connect.Response[v1.UpdateTaskStatusResponse], error)
	// ConvertMessageToReminder turns an existing top-level message into a
	// scheduled reminder owned by the calling agent (atomic create+claim). The
	// message must be a root in the conversation and not already a reminder. The
	// agent is subscribed to the reminder's thread so discussion replies wake it.
	ConvertMessageToReminder(context.Context, *connect.Request[v1.ConvertMessageToReminderRequest]) (*connect.Response[v1.ConvertMessageToReminderResponse], error)
	// ListReminders returns reminders, optionally filtered by owning agent,
	// conversation, and status. Used by the agent-page Reminders tab (user) and
	// the agent CLI (self-list).
	ListReminders(context.Context, *connect.Request[v1.ListRemindersRequest]) (*connect.Response[v1.ListRemindersResponse], error)
	// GetReminder returns a single reminder by its resource name.
	GetReminder(context.Context, *connect.Request[v1.GetReminderRequest]) (*connect.Response[v1.GetReminderResponse], error)
	// UpdateReminder edits the schedule (fire_at/cron_expr/tz) or task_content of
	// a reminder. The caller is the owning agent or a workspace admin. Editing a
	// DUE or MISSED reminder resets it to PENDING with the new schedule.
	UpdateReminder(context.Context, *connect.Request[v1.UpdateReminderRequest]) (*connect.Response[v1.UpdateReminderResponse], error)
	// CancelReminder cancels a reminder. The caller is the owning agent or a
	// workspace admin. A cancelled reminder is terminal.
	CancelReminder(context.Context, *connect.Request[v1.CancelReminderRequest]) (*connect.Response[v1.CancelReminderResponse], error)
	// CompleteReminder marks a DUE reminder completed and atomically posts the
	// result as a single system message in the reminder's thread. Only the owning
	// agent may call this. Recurring reminders reschedule to the next cron fire.
	CompleteReminder(context.Context, *connect.Request[v1.CompleteReminderRequest]) (*connect.Response[v1.CompleteReminderResponse], error)
	// FailReminder marks a DUE reminder failed with the given error and posts it
	// as a system thread message. Recurring reminders reschedule. Only the owning
	// agent may call this.
	FailReminder(context.Context, *connect.Request[v1.FailReminderRequest]) (*connect.Response[v1.FailReminderResponse], error)
	// ListDueReminders returns the DUE reminders owned by the calling agent, for
	// the autonomous drain loop to pick up fired work. Agent identity is resolved
	// from the auth context.
	ListDueReminders(context.Context, *connect.Request[v1.ListDueRemindersRequest]) (*connect.Response[v1.ListDueRemindersResponse], error)
	ListChannelUpdates(context.Context, *connect.Request[v1.ListChannelUpdatesRequest]) (*connect.Response[v1.ListChannelUpdatesResponse], error)
	ListThreadUpdates(context.Context, *connect.Request[v1.ListThreadUpdatesRequest]) (*connect.Response[v1.ListThreadUpdatesResponse], error)
	AckProcessedVersion(context.Context, *connect.Request[v1.AckProcessedVersionRequest]) (*connect.Response[v1.AckProcessedVersionResponse], error)
	FetchConversationActivity(context.Context, *connect.Request[v1.FetchConversationActivityRequest]) (*connect.Response[v1.FetchConversationActivityResponse], error)
	MarkConversationRead(context.Context, *connect.Request[v1.MarkConversationReadRequest]) (*connect.Response[v1.MarkConversationReadResponse], error)
	// UploadFile stores data in S3 and persists a file row. Intended for the
	// agent daemon (browser uploads go through the Echo multipart route). No
	// google.api.http annotation: the agent reaches it via Connect-JSON over the
	// CommandServiceClient, and avoiding a /v1/files/{id} gateway entry keeps it
	// from colliding with the browser download route.
	UploadFile(context.Context, *connect.Request[v1.UploadFileRequest]) (*connect.Response[v1.File], error)
	// DownloadFile fetches a file's bytes from S3. The caller must be a member of
	// the file's conversation. Used by the agent daemon; browser downloads go
	// through the Echo route.
	DownloadFile(context.Context, *connect.Request[v1.DownloadFileRequest]) (*connect.Response[v1.DownloadFileResponse], error)
	// ListFiles returns the files attached to a conversation. The caller must be
	// a member.
	ListFiles(context.Context, *connect.Request[v1.ListFilesRequest]) (*connect.Response[v1.ListFilesResponse], error)
}

